begin;
lock table public.clinical_guidelines in share mode;
lock table public.guideline_versions in share row exclusive mode;
create temporary table marifa_inv_payload on commit drop as
select * from jsonb_to_recordset($marifa_inv$[{"id":"c36e9014-7d53-4a82-b641-8e05a3c9d627","original_version_id":"c36e9014-7d53-4a82-b641-8e05a3c9d627","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Repeated standardised clinic blood-pressure measurement","modalityTarget":"Repeated standardised clinic blood-pressure measurement — Persistent elevated blood pressure","targetCondition":"Persistent elevated blood pressure","expectedFinding":"Repeat valid readings and compare with the current Saudi diagnostic threshold.","clinicalRationale":"Avoids diagnosis from an isolated or technically inaccurate reading.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"specializedAdjunctive","testName":"Home or ambulatory blood-pressure monitoring","modalityTarget":"Home or ambulatory blood-pressure monitoring — Sustained, white-coat or masked hypertension","targetCondition":"Sustained, white-coat or masked hypertension","expectedFinding":"Compare out-of-office averages with clinic readings using the appropriate thresholds.","clinicalRationale":"Confirms the blood-pressure pattern before long-term management decisions.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"laboratory","testName":"Serum creatinine and eGFR","modalityTarget":"Serum creatinine and eGFR — Reduced kidney filtration","targetCondition":"Reduced kidney filtration","expectedFinding":"Raised creatinine or reduced eGFR warrants assessment against prior results.","clinicalRationale":"Detects renal involvement and provides a treatment-safety baseline.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"laboratory","testName":"Serum potassium and sodium","modalityTarget":"Serum potassium and sodium — Electrolyte disturbance","targetCondition":"Electrolyte disturbance","expectedFinding":"Low potassium may suggest a secondary cause or medicine effect.","clinicalRationale":"Identifies secondary-cause clues and informs safe medicine selection.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"laboratory","testName":"Urine albumin-creatinine ratio","modalityTarget":"Urine albumin-creatinine ratio — Renal albumin leakage","targetCondition":"Renal albumin leakage","expectedFinding":"Raised albumin excretion suggests kidney damage; confirm as appropriate.","clinicalRationale":"Identifies renal target-organ involvement and modifies risk assessment.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"laboratory","testName":"Urinalysis","modalityTarget":"Urinalysis — Haematuria, protein or abnormal urinary sediment","targetCondition":"Haematuria, protein or abnormal urinary sediment","expectedFinding":"An abnormal result directs renal evaluation.","clinicalRationale":"Looks for kidney disease as a cause or consequence of hypertension.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"specializedAdjunctive","testName":"12-lead electrocardiogram","modalityTarget":"12-lead electrocardiogram — Left-ventricular hypertrophy, ischaemic change or arrhythmia","targetCondition":"Left-ventricular hypertrophy, ischaemic change or arrhythmia","expectedFinding":"Relevant ECG changes identify cardiac involvement; a normal ECG does not exclude it.","clinicalRationale":"Assesses cardiac consequences and competing cardiovascular disease.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]},{"tier":"laboratory","testName":"Lipid profile and glycaemia assessment","modalityTarget":"Lipid profile and glycaemia assessment — Dyslipidaemia or diabetes accompanying hypertension","targetCondition":"Dyslipidaemia or diabetes accompanying hypertension","expectedFinding":"Abnormal lipid/glucose results change cardiovascular-risk assessment.","clinicalRationale":"Defines coexisting modifiable risk factors.","references":[{"title":"Saudi MOH: Cardiometabolic Risk Management — Assessment of Hypertension","edition":"Legacy manual, PDF pages 35–36; check current local pathway","url":"https://www.moh.gov.sa/en/Ministry/About/Health%20Policies/026.pdf#page=35"}]}],"ruleOut":[{"tier":"laboratory","testName":"Aldosterone-renin testing when primary aldosteronism is suspected","modalityTarget":"Aldosterone-renin testing when primary aldosteronism is suspected — Inappropriate aldosterone activity","targetCondition":"Inappropriate aldosterone activity","expectedFinding":"Interpret the ratio with potassium, medicines and sampling conditions.","clinicalRationale":"Investigates resistant hypertension or relevant hypokalaemia under a specialist/local pathway.","references":[{"title":"MSD Manual Professional: Hypertension — Testing","edition":"Online review updated February 2026; Saudi application awaiting review","url":"https://www.msdmanuals.com/professional/cardiovascular-disorders/hypertension/hypertension"}]},{"tier":"laboratory","testName":"Plasma free metanephrines when pheochromocytoma is suspected","modalityTarget":"Plasma free metanephrines when pheochromocytoma is suspected — Catecholamine excess","targetCondition":"Catecholamine excess","expectedFinding":"Raised results need contextual interpretation and confirmatory assessment.","clinicalRationale":"Investigates suggestive episodic symptoms or other relevant clinical clues.","references":[{"title":"MSD Manual Professional: Hypertension — Testing","edition":"Online review updated February 2026; Saudi application awaiting review","url":"https://www.msdmanuals.com/professional/cardiovascular-disorders/hypertension/hypertension"}]},{"tier":"specializedAdjunctive","testName":"Sleep study when obstructive sleep apnoea is suspected","modalityTarget":"Sleep study when obstructive sleep apnoea is suspected — Sleep-related obstructive breathing events","targetCondition":"Sleep-related obstructive breathing events","expectedFinding":"A diagnostic study establishes clinically important sleep-disordered breathing.","clinicalRationale":"Tests a suspected contributor; it is not routine for every hypertensive patient.","references":[{"title":"MSD Manual Professional: Hypertension — Testing","edition":"Online review updated February 2026; Saudi application awaiting review","url":"https://www.msdmanuals.com/professional/cardiovascular-disorders/hypertension/hypertension"}]}]},"expected_hash":"2dc406ff776c7d23718c4827c0a0e219"},{"id":"83aa7315-9778-4b3a-93a8-edcac20d7c58","original_version_id":"83aa7315-9778-4b3a-93a8-edcac20d7c58","investigations":{"ruleIn":[{"tier":"advancedImaging","testName":"CT abdomen/pelvis when indicated by the surgical team","modalityTarget":"CT abdomen/pelvis when indicated by the surgical team — Obstruction level, transition point, closed loop or bowel compromise","targetCondition":"Obstruction level, transition point, closed loop or bowel compromise","expectedFinding":"Dilated bowel with a transition point; reduced enhancement, free fluid or perforation features raise concern for compromised bowel.","clinicalRationale":"Defines anatomy and complications that change the urgency and type of surgical intervention."},{"tier":"laboratory","testName":"Serum electrolytes and creatinine","modalityTarget":"Serum electrolytes and creatinine — Dehydration, kidney injury and electrolyte losses","targetCondition":"Dehydration, kidney injury and electrolyte losses","expectedFinding":"Potassium or sodium disturbance and rising creatinine after vomiting or reduced intake.","clinicalRationale":"Provides a baseline for fluid replacement and correction of electrolyte losses."}],"ruleOut":[{"tier":"laboratory","testName":"Lactate and blood gas when ischaemia or shock is suspected","modalityTarget":"Lactate and blood gas when ischaemia or shock is suspected — Hypoperfusion and metabolic acidosis","targetCondition":"Hypoperfusion and metabolic acidosis","expectedFinding":"Raised lactate or acidosis increases concern; normal early results do not exclude bowel ischaemia.","clinicalRationale":"Supports urgent reassessment alongside examination and imaging; it cannot safely exclude strangulation alone."}]},"expected_hash":"e0decb00dd2c82ad1844a390a1083162"},{"id":"05481a2b-c95c-440a-a4d0-0c520e8129a4","original_version_id":"05481a2b-c95c-440a-a4d0-0c520e8129a4","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Pulse oximetry","modalityTarget":"Pulse oximetry — Hypoxaemia","targetCondition":"Hypoxaemia","expectedFinding":"Reduced oxygen saturation; oximetry does not measure carbon dioxide or exclude hypercapnia.","clinicalRationale":"Guides titrated oxygen and identifies the need for blood-gas assessment."},{"tier":"laboratory","testName":"Arterial blood gas when respiratory failure is suspected","modalityTarget":"Arterial blood gas when respiratory failure is suspected — Hypercapnia and respiratory acidosis","targetCondition":"Hypercapnia and respiratory acidosis","expectedFinding":"Raised carbon dioxide with reduced pH indicates ventilatory failure; compare with prior results and repeat when clinically indicated.","clinicalRationale":"Helps determine ventilatory support and monitor response to treatment."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Chest radiograph when clinically indicated","modalityTarget":"Chest radiograph when clinically indicated — Pneumonia, pneumothorax or pulmonary oedema","targetCondition":"Pneumonia, pneumothorax or pulmonary oedema","expectedFinding":"New focal opacity, pleural air or congestion suggests a cause beyond an uncomplicated exacerbation.","clinicalRationale":"Identifies treatable mimics and complications that require a different pathway."},{"tier":"specializedAdjunctive","testName":"12-lead ECG when cardiac disease is suspected","modalityTarget":"12-lead ECG when cardiac disease is suspected — Ischaemia or arrhythmia","targetCondition":"Ischaemia or arrhythmia","expectedFinding":"New ischaemic changes or a significant rhythm disturbance; a normal ECG does not exclude coronary disease.","clinicalRationale":"Cardiac disease may precipitate or mimic respiratory deterioration."}]},"expected_hash":"00f814ec31d93ebbc224d432c8bd88fc"},{"id":"336de333-f235-46c4-aa57-2ea4a6e017d5","original_version_id":"336de333-f235-46c4-aa57-2ea4a6e017d5","investigations":{"ruleIn":[{"tier":"firstLineImaging","testName":"Chest radiograph","modalityTarget":"Chest radiograph — Pulmonary congestion and pleural effusions","targetCondition":"Pulmonary congestion and pleural effusions","expectedFinding":"Interstitial or alveolar oedema and effusions may be present; absence does not exclude early heart failure.","clinicalRationale":"Assesses congestion and alternative thoracic causes of acute dyspnoea."},{"tier":"specializedAdjunctive","testName":"Echocardiography","modalityTarget":"Echocardiography — Ventricular dysfunction or an acute structural cause","targetCondition":"Ventricular dysfunction or an acute structural cause","expectedFinding":"Reduced ventricular function, important valve disease or other structural abnormality; preserved ejection fraction does not exclude heart failure.","clinicalRationale":"Defines the cardiac phenotype and detects causes needing urgent specialist intervention."},{"tier":"laboratory","testName":"Creatinine and electrolytes","modalityTarget":"Creatinine and electrolytes — Kidney dysfunction and sodium/potassium disturbance","targetCondition":"Kidney dysfunction and sodium/potassium disturbance","expectedFinding":"Renal impairment or electrolyte abnormality at baseline or during treatment.","clinicalRationale":"Informs safe diuresis, medication selection and monitoring."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"12-lead ECG and troponin when ACS is suspected","modalityTarget":"12-lead ECG and troponin when ACS is suspected — Acute coronary ischaemia or a significant arrhythmia","targetCondition":"Acute coronary ischaemia or a significant arrhythmia","expectedFinding":"Ischaemic ECG changes or a troponin rise/fall require interpretation with symptoms; troponin may rise in heart failure without ACS.","clinicalRationale":"Identifies a precipitant requiring a parallel cardiac emergency pathway."}]},"expected_hash":"78d95438d80ba52422a71de90bb40754"},{"id":"cb0f8932-f4c5-4a6a-9d44-d320713a366b","original_version_id":"cb0f8932-f4c5-4a6a-9d44-d320713a366b","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serial serum creatinine and urine-output measurement","modalityTarget":"Serial serum creatinine and urine-output measurement — An acute decline in kidney function","targetCondition":"An acute decline in kidney function","expectedFinding":"Creatinine rises from the previous baseline and/or urine output falls; creatinine may lag behind the injury.","clinicalRationale":"Establishes the trend and severity and monitors recovery; review prior values rather than one isolated result."},{"tier":"laboratory","testName":"Serum potassium and blood gas when indicated","modalityTarget":"Serum potassium and blood gas when indicated — Hyperkalaemia and metabolic acidosis","targetCondition":"Hyperkalaemia and metabolic acidosis","expectedFinding":"Elevated potassium or reduced bicarbonate/pH; severe abnormalities may require immediate escalation.","clinicalRationale":"Detects life-threatening complications and informs urgent treatment and renal support decisions."},{"tier":"laboratory","testName":"Urine dipstick and microscopy","modalityTarget":"Urine dipstick and microscopy — Glomerular, tubular or infectious clues","targetCondition":"Glomerular, tubular or infectious clues","expectedFinding":"Blood, protein, casts or pyuria direct the differential; findings require clinical interpretation.","clinicalRationale":"Helps distinguish intrinsic renal injury from haemodynamic or obstructive causes."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Renal/bladder ultrasound when obstruction is possible","modalityTarget":"Renal/bladder ultrasound when obstruction is possible — Urinary retention or upper-tract obstruction","targetCondition":"Urinary retention or upper-tract obstruction","expectedFinding":"A distended bladder or hydronephrosis supports obstruction; early obstruction may not produce dilatation.","clinicalRationale":"Identifies a potentially reversible post-renal cause requiring drainage or urological input."}]},"expected_hash":"3ff0b642175a7e452c82d5bd9a51bb50"},{"id":"bb3cbef9-52b1-41f8-b2ee-17078b3a2d5d","original_version_id":"bb3cbef9-52b1-41f8-b2ee-17078b3a2d5d","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serum lipase","modalityTarget":"Serum lipase — Pancreatic inflammation","targetCondition":"Pancreatic inflammation","expectedFinding":"Raised lipase supports pancreatitis with the characteristic clinical picture; elevation alone is not diagnostic.","clinicalRationale":"Provides biochemical evidence while recognising other causes of abdominal pain and enzyme elevation."},{"tier":"laboratory","testName":"Creatinine, electrolytes, glucose and full blood count","modalityTarget":"Creatinine, electrolytes, glucose and full blood count — Volume depletion, metabolic disturbance and organ dysfunction","targetCondition":"Volume depletion, metabolic disturbance and organ dysfunction","expectedFinding":"Renal deterioration, electrolyte/glucose abnormalities or haemoconcentration may accompany severe disease.","clinicalRationale":"Provides a baseline for resuscitation and tracks systemic complications."},{"tier":"specializedAdjunctive","testName":"Abdominal ultrasound and liver tests","modalityTarget":"Abdominal ultrasound and liver tests — Gallstones or biliary obstruction","targetCondition":"Gallstones or biliary obstruction","expectedFinding":"Gallstones, duct dilatation or cholestatic biochemical changes suggest a biliary cause.","clinicalRationale":"Identifies a cause that may require biliary intervention and recurrence prevention."}],"ruleOut":[{"tier":"advancedImaging","testName":"Contrast CT when diagnosis or complications require clarification","modalityTarget":"Contrast CT when diagnosis or complications require clarification — An alternative diagnosis, necrosis or a local collection","targetCondition":"An alternative diagnosis, necrosis or a local collection","expectedFinding":"Pancreatic/peripancreatic changes, necrosis or collections; early imaging can underestimate evolving necrosis.","clinicalRationale":"Answers a specific clinical question when diagnosis is uncertain or deterioration raises concern; it is not routine immediate imaging in every case."}]},"expected_hash":"5e22ecfd17aff7b95e3c54d654fc3713"},{"id":"b2e88f9f-f504-436b-b521-b20ae8767b15","original_version_id":"b2e88f9f-f504-436b-b521-b20ae8767b15","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"12-lead ECG with repeat monitoring when indicated","modalityTarget":"12-lead ECG with repeat monitoring when indicated — Toxic conduction disturbance or arrhythmia","targetCondition":"Toxic conduction disturbance or arrhythmia","expectedFinding":"QRS widening, QT prolongation or a significant rhythm abnormality; changes depend on the toxin and timing.","clinicalRationale":"Identifies cardiotoxic effects that influence monitoring, specialist advice and antidote decisions."},{"tier":"laboratory","testName":"Exposure-specific drug concentration when indicated","modalityTarget":"Exposure-specific drug concentration when indicated — Clinically relevant toxicity from the suspected agent","targetCondition":"Clinically relevant toxicity from the suspected agent","expectedFinding":"Interpret the named drug level against exposure timing and the applicable toxicology pathway.","clinicalRationale":"Use targeted assays that change treatment; a broad toxicology screen cannot exclude poisoning."},{"tier":"laboratory","testName":"Electrolytes, creatinine and blood gas when indicated","modalityTarget":"Electrolytes, creatinine and blood gas when indicated — Acidosis, electrolyte disturbance or kidney injury","targetCondition":"Acidosis, electrolyte disturbance or kidney injury","expectedFinding":"An acid-base or metabolic abnormality may identify severe toxicity or a complication.","clinicalRationale":"Guides supportive care and helps identify exposures needing urgent toxicology input."}],"ruleOut":[{"tier":"laboratory","testName":"Immediate bedside glucose","modalityTarget":"Immediate bedside glucose — Hypoglycaemia as a cause of altered consciousness","targetCondition":"Hypoglycaemia as a cause of altered consciousness","expectedFinding":"A low glucose result identifies a rapidly treatable contributor.","clinicalRationale":"Detects a reversible emergency while exposure assessment and resuscitation proceed."}]},"expected_hash":"9b933da63c71b533feeda32f4b9e1937"},{"id":"6fccc942-c6f3-4ef7-94cf-26fd23edfd27","original_version_id":"6fccc942-c6f3-4ef7-94cf-26fd23edfd27","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serial full blood count","modalityTarget":"Serial full blood count — Anaemia and platelet abnormality","targetCondition":"Anaemia and platelet abnormality","expectedFinding":"Haemoglobin may fall over time; an initially normal value does not exclude significant acute bleeding.","clinicalRationale":"Tracks bleeding and informs transfusion assessment together with haemodynamics and the local protocol."},{"tier":"laboratory","testName":"Blood group and crossmatch","modalityTarget":"Blood group and crossmatch — Compatible blood availability","targetCondition":"Compatible blood availability","expectedFinding":"Compatibility testing identifies suitable blood products; this does not diagnose the bleeding source.","clinicalRationale":"Prepares for transfusion when ongoing bleeding or instability makes it likely."},{"tier":"laboratory","testName":"Urea, creatinine, coagulation and liver tests","modalityTarget":"Urea, creatinine, coagulation and liver tests — Renal impairment, coagulopathy or liver disease","targetCondition":"Renal impairment, coagulopathy or liver disease","expectedFinding":"Renal dysfunction or abnormal coagulation/liver results may increase risk or suggest portal-hypertensive disease.","clinicalRationale":"Informs risk assessment and correction of relevant contributors without delaying resuscitation."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Upper gastrointestinal endoscopy after stabilisation","modalityTarget":"Upper gastrointestinal endoscopy after stabilisation — Bleeding source and high-risk stigmata","targetCondition":"Bleeding source and high-risk stigmata","expectedFinding":"Ulcer, varices or another lesion, with active bleeding or stigmata guiding endoscopic treatment.","clinicalRationale":"Localises the source and permits haemostasis; timing follows the current emergency endoscopy pathway."}]},"expected_hash":"985bd0ee33155714b9f0723cb8bd8748"},{"id":"1dd5fa99-fc60-44e6-94f4-6de6287a1244","original_version_id":"1dd5fa99-fc60-44e6-94f4-6de6287a1244","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Immunisation record and registry reconciliation","modalityTarget":"Immunisation record and registry reconciliation — Missing doses, incomplete courses or undocumented vaccination","targetCondition":"Missing doses, incomplete courses or undocumented vaccination","expectedFinding":"Products and administration dates establish which doses are documented and which remain uncertain.","clinicalRationale":"Prevents missed protection and unnecessary repeat doses using the current Saudi schedule."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Structured contraindication and exposure history","modalityTarget":"Structured contraindication and exposure history — Pregnancy, immunosuppression, prior severe vaccine reaction or exposure risk","targetCondition":"Pregnancy, immunosuppression, prior severe vaccine reaction or exposure risk","expectedFinding":"Relevant conditions or reaction details may change product eligibility or timing.","clinicalRationale":"Selects a safe, risk-appropriate vaccination plan; routine laboratory testing is not required for every vaccine review."}]},"expected_hash":"75bb5e370792fa98dcc5ed0a4d59bf7c"},{"id":"17fa021f-7661-44bf-9e70-1754632b4e9c","original_version_id":"17fa021f-7661-44bf-9e70-1754632b4e9c","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Symptom, function and oxygenation assessment","modalityTarget":"Symptom, function and oxygenation assessment — Breathlessness burden, hypoxaemia and loss of daily function","targetCondition":"Breathlessness burden, hypoxaemia and loss of daily function","expectedFinding":"Document symptom scores, activity limits and saturation in the appropriate clinical context.","clinicalRationale":"Aligns respiratory and comfort care with the patient's goals; breathlessness alone is not proof of hypoxaemia."},{"tier":"laboratory","testName":"Blood gas when hypercapnia or ventilatory failure is suspected","modalityTarget":"Blood gas when hypercapnia or ventilatory failure is suspected — Carbon-dioxide retention and acidosis","targetCondition":"Carbon-dioxide retention and acidosis","expectedFinding":"Raised carbon dioxide and reduced pH support ventilatory failure.","clinicalRationale":"Determines whether respiratory support assessment is appropriate within the agreed goals of care."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Targeted chest imaging for a new clinical change","modalityTarget":"Targeted chest imaging for a new clinical change — Pneumonia, pneumothorax or pulmonary oedema","targetCondition":"Pneumonia, pneumothorax or pulmonary oedema","expectedFinding":"A new opacity, pleural air or congestion may explain deterioration.","clinicalRationale":"Investigate reversible causes when the result will change goal-concordant treatment."}]},"expected_hash":"2154f0bb35abda77550361d63e4e1af6"},{"id":"7c1b7028-68a7-4fdb-ae44-be27da67e5e1","original_version_id":"7c1b7028-68a7-4fdb-ae44-be27da67e5e1","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Observational pain assessment and collateral history","modalityTarget":"Observational pain assessment and collateral history — Pain or distress in a person unable to report symptoms reliably","targetCondition":"Pain or distress in a person unable to report symptoms reliably","expectedFinding":"Changes in facial expression, movement, vocalisation or usual behaviour suggest distress but are not specific for pain.","clinicalRationale":"Supports symptom relief and avoids attributing every behavioural change to dementia."},{"tier":"specializedAdjunctive","testName":"Swallowing and nutritional assessment","modalityTarget":"Swallowing and nutritional assessment — Dysphagia, aspiration risk and inadequate intake","targetCondition":"Dysphagia, aspiration risk and inadequate intake","expectedFinding":"Coughing with meals, unsafe swallowing or progressive weight/intake loss informs an individualised feeding plan.","clinicalRationale":"Guides comfort, feeding support and discussion of benefits and burdens."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused examination and medication review for new deterioration","modalityTarget":"Focused examination and medication review for new deterioration — Delirium, retention, constipation, infection or drug-related harm","targetCondition":"Delirium, retention, constipation, infection or drug-related harm","expectedFinding":"A new focal finding or temporal relationship to medication change directs proportionate investigation.","clinicalRationale":"Identifies potentially reversible distress; order further tests only when they can improve goal-concordant care."}]},"expected_hash":"2464114f0f51e05f89f6a13bcac51514"},{"id":"1f3a8674-fb1a-4c14-9744-8ae2d3eed686","original_version_id":"1f3a8674-fb1a-4c14-9744-8ae2d3eed686","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Symptom, volume-status and functional assessment","modalityTarget":"Symptom, volume-status and functional assessment — Congestion and symptom burden","targetCondition":"Congestion and symptom burden","expectedFinding":"Increasing oedema, orthopnoea, weight or functional limitation suggests deterioration; examine in context.","clinicalRationale":"Guides symptom treatment and shared decisions about the burden of further intervention."},{"tier":"laboratory","testName":"Creatinine and electrolytes when results will change care","modalityTarget":"Creatinine and electrolytes when results will change care — Kidney dysfunction and treatment-related electrolyte disturbance","targetCondition":"Kidney dysfunction and treatment-related electrolyte disturbance","expectedFinding":"A rise in creatinine or potassium/sodium abnormality may limit medicine tolerance.","clinicalRationale":"Supports safe symptom treatment and proportionate monitoring."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"ECG for a new rhythm or ischaemic concern","modalityTarget":"ECG for a new rhythm or ischaemic concern — Arrhythmia or a possible ischaemic precipitant","targetCondition":"Arrhythmia or a possible ischaemic precipitant","expectedFinding":"A new rhythm disturbance or ischaemic change directs further cardiac assessment.","clinicalRationale":"Identifies a reversible cause when investigation and treatment fit the agreed care goals."}]},"expected_hash":"c9c6b2f1f6f38166f20efe9b8162df57"},{"id":"3f22251d-c5e6-4dfa-b52c-599b05e0bd4c","original_version_id":"3f22251d-c5e6-4dfa-b52c-599b05e0bd4c","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Dating ultrasound and gestation-appropriate fetal screening","modalityTarget":"Dating ultrasound and gestation-appropriate fetal screening — Gestational age, fetal number and structural/developmental concerns","targetCondition":"Gestational age, fetal number and structural/developmental concerns","expectedFinding":"Biometry establishes dating; screening findings may identify a need for specialist assessment rather than a definitive diagnosis.","clinicalRationale":"Sets the pregnancy timetable and offers informed, risk-appropriate screening under the Saudi antenatal pathway."},{"tier":"laboratory","testName":"Full blood count","modalityTarget":"Full blood count — Anaemia or platelet abnormality","targetCondition":"Anaemia or platelet abnormality","expectedFinding":"Low haemoglobin or abnormal platelets require assessment using pregnancy-appropriate reference ranges.","clinicalRationale":"Detects maternal haematological problems that influence care and delivery planning."},{"tier":"laboratory","testName":"Blood group, RhD and antibody screen","modalityTarget":"Blood group, RhD and antibody screen — RhD status and clinically significant red-cell antibodies","targetCondition":"RhD status and clinically significant red-cell antibodies","expectedFinding":"Antibody identification determines whether fetal risk or specialist follow-up is present.","clinicalRationale":"Supports alloimmunisation prevention and management using the current obstetric protocol."}],"ruleOut":[{"tier":"laboratory","testName":"Infection screening selected by the antenatal pathway","modalityTarget":"Infection screening selected by the antenatal pathway — Maternal infection with implications for pregnancy or the newborn","targetCondition":"Maternal infection with implications for pregnancy or the newborn","expectedFinding":"Interpret each named assay using the current screening/confirmation algorithm.","clinicalRationale":"Enables timely maternal treatment and prevention of transmission; the exact tests and consent requirements follow local policy."}]},"expected_hash":"3605057917534cfce84fef224426ae9b"},{"id":"ce9316d7-2fe5-415d-a633-b0ebb79a4693","original_version_id":"ce9316d7-2fe5-415d-a633-b0ebb79a4693","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Spirometry with bronchodilator response","modalityTarget":"Spirometry with bronchodilator response — Variable expiratory airflow limitation","targetCondition":"Variable expiratory airflow limitation","expectedFinding":"Obstruction with reversibility supports asthma; normal spirometry between episodes does not exclude it.","clinicalRationale":"Provides objective support for the diagnosis instead of relying on symptoms alone."},{"tier":"specializedAdjunctive","testName":"Peak-flow diary when indicated","modalityTarget":"Peak-flow diary when indicated — Variability in expiratory airflow","targetCondition":"Variability in expiratory airflow","expectedFinding":"Variation over time or with exposure supports variable airflow limitation when measurements are reliable.","clinicalRationale":"Helps investigate intermittent or work-related symptoms when office spirometry is inconclusive."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused assessment for competing causes of wheeze or dyspnoea","modalityTarget":"Focused assessment for competing causes of wheeze or dyspnoea — COPD, cardiac disease, upper-airway dysfunction or another mimic","targetCondition":"COPD, cardiac disease, upper-airway dysfunction or another mimic","expectedFinding":"Smoking history, fixed obstruction, cardiac signs or upper-airway symptoms direct additional testing.","clinicalRationale":"Prevents misdiagnosis; select a named additional test only for the suspected alternative."}]},"expected_hash":"df836b670f37a50a5b67862e15a073f5"},{"id":"d2743507-415a-4bc7-8857-3604c97bab42","original_version_id":"d2743507-415a-4bc7-8857-3604c97bab42","investigations":{"ruleIn":[{"tier":"firstLineImaging","testName":"Screening mammography when eligible","modalityTarget":"Screening mammography when eligible — Suspicious breast lesions before symptoms develop","targetCondition":"Suspicious breast lesions before symptoms develop","expectedFinding":"A recall or abnormal imaging category requires further assessment; a negative screen does not explain a new symptom.","clinicalRationale":"Detects possible early disease in eligible asymptomatic patients after discussion of benefits and harms."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Structured breast-cancer risk and symptom assessment","modalityTarget":"Structured breast-cancer risk and symptom assessment — High-risk family history or a symptom requiring diagnostic assessment","targetCondition":"High-risk family history or a symptom requiring diagnostic assessment","expectedFinding":"A lump, skin/nipple change or important hereditary pattern changes the pathway.","clinicalRationale":"Separates asymptomatic screening from symptomatic diagnosis and selects the appropriate Saudi programme or specialist referral."}]},"expected_hash":"ca3a8ea7a7783baaacb2519c05de9489"},{"id":"cc78da1f-1df1-477a-b691-56ef783e4054","original_version_id":"cc78da1f-1df1-477a-b691-56ef783e4054","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Pain score, pain-character and neurological assessment","modalityTarget":"Pain score, pain-character and neurological assessment — Pain severity, neuropathic features and neurological compromise","targetCondition":"Pain severity, neuropathic features and neurological compromise","expectedFinding":"Document intensity, interference, neuropathic descriptors and any motor/sensory deficit.","clinicalRationale":"Defines the likely pain mechanism and identifies emergencies such as possible cord compression."},{"tier":"laboratory","testName":"Creatinine and liver tests when prescribing decisions require them","modalityTarget":"Creatinine and liver tests when prescribing decisions require them — Impaired drug clearance","targetCondition":"Impaired drug clearance","expectedFinding":"Renal or hepatic dysfunction may increase medicine accumulation and toxicity.","clinicalRationale":"Informs analgesic selection and monitoring under the palliative formulary."}],"ruleOut":[{"tier":"advancedImaging","testName":"Targeted imaging for suspected structural complication","modalityTarget":"Targeted imaging for suspected structural complication — Pathological fracture, spinal cord compression or obstructive disease","targetCondition":"Pathological fracture, spinal cord compression or obstructive disease","expectedFinding":"Imaging may show the lesion responsible for focal pain or new neurological signs.","clinicalRationale":"Identifies a treatable complication; choose the modality and urgency for the specific clinical question."}]},"expected_hash":"547893fc74fa15628d10948f0b13f1a6"},{"id":"3eaa3e4b-00e8-4bb1-b98a-c18526c67c8e","original_version_id":"3eaa3e4b-00e8-4bb1-b98a-c18526c67c8e","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Standardised blood-pressure measurement","modalityTarget":"Standardised blood-pressure measurement — Sustained elevated blood pressure","targetCondition":"Sustained elevated blood pressure","expectedFinding":"Repeated readings and out-of-office confirmation distinguish persistent elevation from measurement effects.","clinicalRationale":"Provides an accurate modifiable-risk measure for the overall cardiovascular assessment."},{"tier":"laboratory","testName":"Lipid profile","modalityTarget":"Lipid profile — Atherogenic lipid burden","targetCondition":"Atherogenic lipid burden","expectedFinding":"LDL and other lipid fractions inform risk estimation and possible inherited dyslipidaemia.","clinicalRationale":"Supports prevention decisions alongside age, smoking, diabetes and established vascular disease."}],"ruleOut":[{"tier":"laboratory","testName":"HbA1c or fasting glucose and kidney assessment when indicated","modalityTarget":"HbA1c or fasting glucose and kidney assessment when indicated — Diabetes or chronic kidney disease modifying cardiovascular risk","targetCondition":"Diabetes or chronic kidney disease modifying cardiovascular risk","expectedFinding":"Abnormal glycaemia, reduced filtration or albuminuria changes risk categorisation.","clinicalRationale":"Identifies important comorbidity; use a locally accepted risk method and confirm abnormalities appropriately."}]},"expected_hash":"514082facdc4ea9578ee578c3ddc6f42"},{"id":"eab57274-e256-4281-bd97-7ebe1fb49472","original_version_id":"eab57274-e256-4281-bd97-7ebe1fb49472","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Visual acuity and slit-lamp examination","modalityTarget":"Visual acuity and slit-lamp examination — Lens opacity and its effect on vision","targetCondition":"Lens opacity and its effect on vision","expectedFinding":"A cataract consistent with symptoms supports the diagnosis; acuity alone does not establish the cause.","clinicalRationale":"Determines whether cataract is the main source of visual disability and whether surgery is likely to help."},{"tier":"specializedAdjunctive","testName":"Ocular biometry","modalityTarget":"Ocular biometry — Measurements needed for intraocular-lens selection","targetCondition":"Measurements needed for intraocular-lens selection","expectedFinding":"Axial length and corneal measurements guide lens-power calculation.","clinicalRationale":"Supports surgical planning and reduces avoidable refractive error."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Retinal and optic-nerve assessment","modalityTarget":"Retinal and optic-nerve assessment — Other ocular disease limiting postoperative vision","targetCondition":"Other ocular disease limiting postoperative vision","expectedFinding":"Macular, retinal or optic-nerve abnormalities may reduce the expected benefit.","clinicalRationale":"Identifies competing causes of poor vision and informs consent and referral."}]},"expected_hash":"ec1aaf5e745a247cc6e268e843a8a785"},{"id":"3f47a009-d923-4a43-bce4-9357e38111e7","original_version_id":"3f47a009-d923-4a43-bce4-9357e38111e7","investigations":{"ruleIn":[{"tier":"laboratory","testName":"HPV testing or cervical cytology according to the adopted programme","modalityTarget":"HPV testing or cervical cytology according to the adopted programme — High-risk HPV or abnormal cervical cells","targetCondition":"High-risk HPV or abnormal cervical cells","expectedFinding":"A positive HPV result or abnormal cytology requires risk-based triage; neither alone establishes invasive cancer.","clinicalRationale":"Detects risk or precancer in eligible patients and determines tracked follow-up."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Colposcopy and directed biopsy when indicated","modalityTarget":"Colposcopy and directed biopsy when indicated — Cervical intraepithelial neoplasia or invasive disease","targetCondition":"Cervical intraepithelial neoplasia or invasive disease","expectedFinding":"Histology defines the lesion and grade after an abnormal screen or suspicious examination.","clinicalRationale":"Provides diagnostic confirmation before treatment planning."}]},"expected_hash":"9c4fac7f77edb0dfd6efb39fe3d38399"},{"id":"81ec89af-5bc1-40e0-bf3b-52097c45af9f","original_version_id":"81ec89af-5bc1-40e0-bf3b-52097c45af9f","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Official vaccination record reconciliation","modalityTarget":"Official vaccination record reconciliation — Missing doses and valid prior immunisations","targetCondition":"Missing doses and valid prior immunisations","expectedFinding":"Product, date and dose spacing establish documented protection and catch-up needs.","clinicalRationale":"Builds a catch-up plan using the current Saudi childhood schedule rather than restarting courses automatically."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Contraindication and immune-status history","modalityTarget":"Contraindication and immune-status history — Severe prior reactions or conditions affecting vaccine eligibility","targetCondition":"Severe prior reactions or conditions affecting vaccine eligibility","expectedFinding":"Immunosuppression or a relevant serious reaction may change product choice or timing.","clinicalRationale":"Avoids inappropriate vaccination and identifies children needing specialist advice; routine blood tests are not required for every catch-up visit."}]},"expected_hash":"09ab86185af7212d2edde153627c596d"},{"id":"2a6b90b6-13a1-443f-a212-1c2f3975327d","original_version_id":"2a6b90b6-13a1-443f-a212-1c2f3975327d","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serial creatinine/eGFR and urine albumin-creatinine ratio","modalityTarget":"Serial creatinine/eGFR and urine albumin-creatinine ratio — Persistent reduced filtration or kidney damage","targetCondition":"Persistent reduced filtration or kidney damage","expectedFinding":"Persistent eGFR reduction or albuminuria over the required chronicity interval supports CKD.","clinicalRationale":"Confirms chronicity and stratifies kidney/cardiovascular risk instead of labelling one abnormal result as CKD."},{"tier":"laboratory","testName":"Electrolytes and full blood count","modalityTarget":"Electrolytes and full blood count — Hyperkalaemia, acid-base disturbance or anaemia","targetCondition":"Hyperkalaemia, acid-base disturbance or anaemia","expectedFinding":"Potassium, bicarbonate or haemoglobin abnormalities identify complications requiring assessment.","clinicalRationale":"Guides monitoring and management proportionate to disease stage and treatment."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Urinalysis and renal ultrasound when the cause or obstruction is uncertain","modalityTarget":"Urinalysis and renal ultrasound when the cause or obstruction is uncertain — Intrinsic kidney disease or obstruction","targetCondition":"Intrinsic kidney disease or obstruction","expectedFinding":"Haematuria/casts or structural abnormalities direct cause-specific evaluation.","clinicalRationale":"Identifies a potentially treatable cause and helps distinguish chronic disease from a new reversible process."}]},"expected_hash":"9f8b0791aeb428127b7be7520be53cb0"},{"id":"e5bf7644-f824-4eca-8828-aacf30dad973","original_version_id":"e5bf7644-f824-4eca-8828-aacf30dad973","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Post-bronchodilator spirometry","modalityTarget":"Post-bronchodilator spirometry — Persistent expiratory airflow obstruction","targetCondition":"Persistent expiratory airflow obstruction","expectedFinding":"Persistent obstruction in the appropriate exposure/symptom context supports COPD.","clinicalRationale":"Provides objective diagnostic evidence and distinguishes symptoms from documented airflow limitation."},{"tier":"specializedAdjunctive","testName":"Symptom and exacerbation-history assessment","modalityTarget":"Symptom and exacerbation-history assessment — Activity limitation and future exacerbation risk","targetCondition":"Activity limitation and future exacerbation risk","expectedFinding":"Validated symptom measures and prior exacerbations identify the clinical burden.","clinicalRationale":"Guides individualised ongoing care beyond spirometric severity alone."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Oximetry and targeted chest imaging when indicated","modalityTarget":"Oximetry and targeted chest imaging when indicated — Hypoxaemia or an alternative thoracic diagnosis","targetCondition":"Hypoxaemia or an alternative thoracic diagnosis","expectedFinding":"Low saturation, a focal lesion or another radiographic abnormality directs further investigation.","clinicalRationale":"Identifies complications or mimics; routine repeated imaging is not justified without a clinical question."}]},"expected_hash":"408789f6810322ca6190ec566c08f7b1"},{"id":"433ede2c-6a49-4169-88ca-298ccf2cb065","original_version_id":"433ede2c-6a49-4169-88ca-298ccf2cb065","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Colonoscopy with biopsy","modalityTarget":"Colonoscopy with biopsy — Colorectal lesion and histological diagnosis","targetCondition":"Colorectal lesion and histological diagnosis","expectedFinding":"A suspicious lesion with histology establishes tumour type; complete colonic evaluation assesses synchronous lesions when feasible.","clinicalRationale":"Confirms diagnosis before cancer treatment decisions."},{"tier":"advancedImaging","testName":"CT staging according to the oncology pathway","modalityTarget":"CT staging according to the oncology pathway — Regional and distant disease","targetCondition":"Regional and distant disease","expectedFinding":"Nodes and distant lesions influence stage and operability; indeterminate lesions need further evaluation.","clinicalRationale":"Defines extent for multidisciplinary treatment planning."}],"ruleOut":[{"tier":"laboratory","testName":"Full blood count and renal/liver tests","modalityTarget":"Full blood count and renal/liver tests — Anaemia and organ dysfunction affecting treatment fitness","targetCondition":"Anaemia and organ dysfunction affecting treatment fitness","expectedFinding":"Iron-deficiency-pattern anaemia or kidney/liver impairment requires assessment.","clinicalRationale":"Identifies complications and provides a baseline for safe procedures and systemic therapy."}]},"expected_hash":"1e647c71b02039d2455e7a4e21f885c0"},{"id":"d0389517-2846-49bc-8a01-eb7265f8e139","original_version_id":"d0389517-2846-49bc-8a01-eb7265f8e139","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Faecal immunochemical test when used by the national programme","modalityTarget":"Faecal immunochemical test when used by the national programme — Occult lower-gastrointestinal bleeding","targetCondition":"Occult lower-gastrointestinal bleeding","expectedFinding":"A positive result requires follow-up investigation; a negative screen does not exclude cancer in a symptomatic patient.","clinicalRationale":"Selects eligible asymptomatic patients for further assessment through a tracked programme."},{"tier":"specializedAdjunctive","testName":"Colonoscopy after a positive screen or other indication","modalityTarget":"Colonoscopy after a positive screen or other indication — Polyps or a colorectal tumour","targetCondition":"Polyps or a colorectal tumour","expectedFinding":"Direct visualisation and histology identify the lesion and determine the next step.","clinicalRationale":"Completes diagnostic follow-up rather than repeating a positive screening test to dismiss it."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Risk and symptom assessment","modalityTarget":"Risk and symptom assessment — Symptoms or high-risk history requiring a diagnostic/surveillance pathway","targetCondition":"Symptoms or high-risk history requiring a diagnostic/surveillance pathway","expectedFinding":"Bleeding, iron-deficiency anaemia, prior polyps or hereditary risk changes the pathway.","clinicalRationale":"Avoids using routine screening to reassure a symptomatic or high-risk patient."}]},"expected_hash":"c9784bb168c5e372479e346e4a659268"},{"id":"a44b31ff-1839-4db9-aec2-f73fcaef4d5f","original_version_id":"a44b31ff-1839-4db9-aec2-f73fcaef4d5f","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Symptom, function and goals-of-care assessment","modalityTarget":"Symptom, function and goals-of-care assessment — Uraemic symptom burden and priorities","targetCondition":"Uraemic symptom burden and priorities","expectedFinding":"Document pruritus, nausea, breathlessness, function and the person's preferred care limits.","clinicalRationale":"Aligns monitoring and interventions with comfort and shared decisions."},{"tier":"laboratory","testName":"Potassium, bicarbonate and creatinine when results will change care","modalityTarget":"Potassium, bicarbonate and creatinine when results will change care — Electrolyte/acidosis complications and kidney trajectory","targetCondition":"Electrolyte/acidosis complications and kidney trajectory","expectedFinding":"Abnormal potassium/bicarbonate or a changing filtration trend may explain symptoms and identify treatment options.","clinicalRationale":"Uses proportionate testing for manageable complications rather than routine burdensome testing without a decision."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused examination and medication review after new deterioration","modalityTarget":"Focused examination and medication review after new deterioration — Fluid overload, infection or drug-related harm","targetCondition":"Fluid overload, infection or drug-related harm","expectedFinding":"A new focal finding or exposure directs additional investigation.","clinicalRationale":"Identifies reversible problems within the agreed conservative-care plan."}]},"expected_hash":"cd2ebf621195297a9283d013e7f115f4"},{"id":"732644b9-0497-44a8-bfc2-0fca5dfc7392","original_version_id":"732644b9-0497-44a8-bfc2-0fca5dfc7392","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Collateral history and validated delirium assessment","modalityTarget":"Collateral history and validated delirium assessment — Acute fluctuating inattention or cognitive change","targetCondition":"Acute fluctuating inattention or cognitive change","expectedFinding":"A change from baseline with fluctuation and impaired attention supports delirium.","clinicalRationale":"Distinguishes delirium from chronic cognitive impairment and establishes the time course."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Pain, bladder, bowel and medication assessment","modalityTarget":"Pain, bladder, bowel and medication assessment — Reversible causes of distress","targetCondition":"Reversible causes of distress","expectedFinding":"Pain, retention, constipation or a recent deliriogenic medicine may explain agitation.","clinicalRationale":"Detects treatable contributors without automatically adding invasive investigations."},{"tier":"laboratory","testName":"Targeted glucose, electrolytes or infection tests when goal-concordant","modalityTarget":"Targeted glucose, electrolytes or infection tests when goal-concordant — A suspected metabolic or infectious precipitant","targetCondition":"A suspected metabolic or infectious precipitant","expectedFinding":"An abnormal result is interpreted against the suspected cause and goals of care.","clinicalRationale":"Order only the named tests likely to change symptom-focused treatment."}]},"expected_hash":"f7442b3c7faa4bfc167f459650656221"},{"id":"e483d190-076c-49b3-881c-78ca823af167","original_version_id":"e483d190-076c-49b3-881c-78ca823af167","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Laboratory HbA1c when appropriate","modalityTarget":"Laboratory HbA1c when appropriate — Chronic hyperglycaemia","targetCondition":"Chronic hyperglycaemia","expectedFinding":"An elevated result requires interpretation using the adopted diagnostic pathway; altered red-cell turnover can make it unreliable.","clinicalRationale":"Assesses longer-term glycaemia without fasting when the assay is suitable for the patient."},{"tier":"laboratory","testName":"Fasting plasma glucose","modalityTarget":"Fasting plasma glucose — Fasting hyperglycaemia","targetCondition":"Fasting hyperglycaemia","expectedFinding":"An abnormal fasting value supports dysglycaemia and may require confirmation if the patient is asymptomatic.","clinicalRationale":"Provides a glucose-based assessment when HbA1c is unsuitable or as an alternative screening method."}],"ruleOut":[{"tier":"laboratory","testName":"Repeat diagnostic testing when required","modalityTarget":"Repeat diagnostic testing when required — Persistent rather than isolated hyperglycaemia","targetCondition":"Persistent rather than isolated hyperglycaemia","expectedFinding":"Concordant abnormal laboratory results confirm persistence according to the adopted criteria.","clinicalRationale":"Reduces misclassification from biological variation, acute illness or testing error."}]},"expected_hash":"2fa7984b209f4d027c2df5971d3071de"},{"id":"625f0d83-3863-47f9-a64e-55c0355f3240","original_version_id":"625f0d83-3863-47f9-a64e-55c0355f3240","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Blood glucose and blood ketones","modalityTarget":"Blood glucose and blood ketones — Hyperglycaemia and ketonaemia","targetCondition":"Hyperglycaemia and ketonaemia","expectedFinding":"Raised ketones with the clinical context support DKA; glucose may be less elevated in euglycaemic DKA.","clinicalRationale":"Detects the metabolic emergency and tracks ketone resolution alongside acid-base results."},{"tier":"laboratory","testName":"Venous blood gas and electrolytes","modalityTarget":"Venous blood gas and electrolytes — Metabolic acidosis and potassium disturbance","targetCondition":"Metabolic acidosis and potassium disturbance","expectedFinding":"Reduced pH/bicarbonate with ketonaemia supports ketoacidosis; measured potassium may mask total-body depletion.","clinicalRationale":"Defines severity and guides safe treatment and monitoring under the current Saudi DKA protocol."},{"tier":"laboratory","testName":"Creatinine and fluid-balance assessment","modalityTarget":"Creatinine and fluid-balance assessment — Dehydration and kidney impairment","targetCondition":"Dehydration and kidney impairment","expectedFinding":"Renal deterioration and fluid-balance changes help define volume loss and treatment tolerance.","clinicalRationale":"Supports individualised fluid management and complication surveillance."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"ECG and source-directed infection tests when indicated","modalityTarget":"ECG and source-directed infection tests when indicated — A cardiac/infectious precipitant or electrolyte-related arrhythmia","targetCondition":"A cardiac/infectious precipitant or electrolyte-related arrhythmia","expectedFinding":"ECG abnormalities or a positive source investigation directs parallel management; avoid indiscriminate cultures.","clinicalRationale":"Identifies and treats the trigger without delaying the metabolic emergency pathway."}]},"expected_hash":"bf336af5ef9dbac8ebb0d408d84ca331"},{"id":"65fce08b-a289-44bd-9c91-79b2243f824c","original_version_id":"65fce08b-a289-44bd-9c91-79b2243f824c","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Lipid profile","modalityTarget":"Lipid profile — LDL elevation and triglyceride abnormality","targetCondition":"LDL elevation and triglyceride abnormality","expectedFinding":"The lipid pattern and degree of elevation inform risk and possible inherited disease.","clinicalRationale":"Provides the baseline for prevention decisions and later response assessment."},{"tier":"specializedAdjunctive","testName":"Family history and vascular-risk assessment","modalityTarget":"Family history and vascular-risk assessment — Premature atherosclerosis or familial dyslipidaemia","targetCondition":"Premature atherosclerosis or familial dyslipidaemia","expectedFinding":"Premature events, markedly elevated historical LDL or affected relatives may warrant specialist evaluation.","clinicalRationale":"Determines prevention intensity and whether family assessment is appropriate."}],"ruleOut":[{"tier":"laboratory","testName":"TSH, glycaemia, renal or liver tests when a secondary cause is suspected","modalityTarget":"TSH, glycaemia, renal or liver tests when a secondary cause is suspected — Hypothyroidism, diabetes or organ disease contributing to dyslipidaemia","targetCondition":"Hypothyroidism, diabetes or organ disease contributing to dyslipidaemia","expectedFinding":"A relevant biochemical abnormality redirects assessment to a secondary contributor.","clinicalRationale":"Tests the specific suspected cause rather than assuming all abnormal lipids are primary."}]},"expected_hash":"282e677480e47cfbce54b054da4d1313"},{"id":"c5e62cae-fb6e-47ef-8681-bec748e64dd4","original_version_id":"c5e62cae-fb6e-47ef-8681-bec748e64dd4","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Review of coronary angiography and ischaemia evidence","modalityTarget":"Review of coronary angiography and ischaemia evidence — Coronary anatomy and clinically important ischaemia","targetCondition":"Coronary anatomy and clinically important ischaemia","expectedFinding":"Anatomical stenoses and functional evidence are assessed together; anatomy alone does not establish benefit from intervention.","clinicalRationale":"Supports Heart Team selection of revascularisation strategy and shared consent."},{"tier":"specializedAdjunctive","testName":"Echocardiography","modalityTarget":"Echocardiography — Ventricular function and associated valve disease","targetCondition":"Ventricular function and associated valve disease","expectedFinding":"Systolic dysfunction or important valve pathology influences procedural risk and planning.","clinicalRationale":"Defines cardiac function before the proposed intervention."}],"ruleOut":[{"tier":"laboratory","testName":"Full blood count, creatinine and medication review","modalityTarget":"Full blood count, creatinine and medication review — Anaemia, kidney dysfunction and bleeding/antithrombotic risk","targetCondition":"Anaemia, kidney dysfunction and bleeding/antithrombotic risk","expectedFinding":"Anaemia or impaired kidney function may require optimisation; document antiplatelet and anticoagulant exposure.","clinicalRationale":"Plans safe contrast/procedural care and avoids preventable bleeding or medicine interruption."}]},"expected_hash":"8a8884a95504171fa5ae9d0feb4d14b5"},{"id":"2ebb8b8e-91bd-44ef-98f9-24daa70738d4","original_version_id":"2ebb8b8e-91bd-44ef-98f9-24daa70738d4","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Standing and supine groin/abdominal examination","modalityTarget":"Standing and supine groin/abdominal examination — Hernia location, reducibility and complication signs","targetCondition":"Hernia location, reducibility and complication signs","expectedFinding":"A cough impulse or reducible bulge supports hernia; painful irreducibility requires urgent assessment.","clinicalRationale":"Defines the clinical diagnosis and separates an elective case from possible incarceration or strangulation."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Ultrasound when examination is inconclusive","modalityTarget":"Ultrasound when examination is inconclusive — An occult hernia or alternative groin mass","targetCondition":"An occult hernia or alternative groin mass","expectedFinding":"Dynamic imaging may demonstrate a defect or another lesion.","clinicalRationale":"Clarifies uncertain anatomy rather than routinely imaging every clinically evident hernia."},{"tier":"specializedAdjunctive","testName":"Targeted anaesthetic and medication assessment","modalityTarget":"Targeted anaesthetic and medication assessment — Modifiable perioperative risk","targetCondition":"Modifiable perioperative risk","expectedFinding":"Cardiopulmonary disease, anticoagulation or impaired functional status directs specific additional testing.","clinicalRationale":"Selects preoperative tests according to comorbidity and planned anaesthesia."}]},"expected_hash":"ed6d0c92fd3bad300bc32d74900e8a14"},{"id":"090cabb1-daef-487b-a0cf-4f36c4e6fb30","original_version_id":"090cabb1-daef-487b-a0cf-4f36c4e6fb30","investigations":{"ruleIn":[{"tier":"firstLineImaging","testName":"Joint radiographs and functional assessment","modalityTarget":"Joint radiographs and functional assessment — Structural joint disease matching symptoms","targetCondition":"Structural joint disease matching symptoms","expectedFinding":"Degenerative change and documented disability are considered together; radiographic severity alone does not determine the need for surgery.","clinicalRationale":"Confirms the indication and supports shared expectations about benefit."},{"tier":"laboratory","testName":"Full blood count and renal/metabolic tests when indicated","modalityTarget":"Full blood count and renal/metabolic tests when indicated — Anaemia and organ dysfunction requiring optimisation","targetCondition":"Anaemia and organ dysfunction requiring optimisation","expectedFinding":"Low haemoglobin or renal/metabolic abnormalities may alter preparation.","clinicalRationale":"Identifies treatable perioperative risks under the local preoperative pathway."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Infection, skin and medication assessment","modalityTarget":"Infection, skin and medication assessment — Active infection or medication-related surgical risk","targetCondition":"Active infection or medication-related surgical risk","expectedFinding":"An active infection, wound problem or relevant medicine exposure requires review.","clinicalRationale":"Reduces avoidable postoperative complications and selects further tests only for identified concerns."}]},"expected_hash":"392c776ebdeb990ff0737c6f23c51d15"},{"id":"78cec019-7976-489a-a4c9-fdd6f7c316c7","original_version_id":"78cec019-7976-489a-a4c9-fdd6f7c316c7","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Pelvic examination and ultrasound when indicated","modalityTarget":"Pelvic examination and ultrasound when indicated — The structural cause of symptoms and operative anatomy","targetCondition":"The structural cause of symptoms and operative anatomy","expectedFinding":"Fibroids, adnexal pathology or other pelvic findings influence the indication and approach.","clinicalRationale":"Confirms that the planned operation addresses the identified problem."},{"tier":"laboratory","testName":"Full blood count and iron assessment when bleeding suggests deficiency","modalityTarget":"Full blood count and iron assessment when bleeding suggests deficiency — Anaemia or iron depletion","targetCondition":"Anaemia or iron depletion","expectedFinding":"Reduced haemoglobin and iron indices support blood-loss-related deficiency.","clinicalRationale":"Enables preoperative optimisation and blood-management planning."}],"ruleOut":[{"tier":"laboratory","testName":"Pregnancy testing with consent when relevant","modalityTarget":"Pregnancy testing with consent when relevant — An unrecognised pregnancy","targetCondition":"An unrecognised pregnancy","expectedFinding":"A positive result changes the operative plan and requires pregnancy-specific assessment.","clinicalRationale":"Avoids proceeding with an elective intervention before pregnancy status is addressed."},{"tier":"specializedAdjunctive","testName":"Endometrial sampling when age, bleeding pattern or risk indicates it","modalityTarget":"Endometrial sampling when age, bleeding pattern or risk indicates it — Endometrial hyperplasia or malignancy","targetCondition":"Endometrial hyperplasia or malignancy","expectedFinding":"Histology identifies disease that may require an oncology rather than benign-surgery pathway.","clinicalRationale":"Excludes an important alternative before finalising treatment and surgical route."}]},"expected_hash":"30e74f3801d1ec3ef5ca0b52e456d1fc"},{"id":"6348dfb9-f42c-4745-b038-ee84d31c521c","original_version_id":"6348dfb9-f42c-4745-b038-ee84d31c521c","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Comprehensive echocardiography","modalityTarget":"Comprehensive echocardiography — Valve lesion severity and ventricular response","targetCondition":"Valve lesion severity and ventricular response","expectedFinding":"Valve haemodynamics, chamber size and ventricular function define the lesion in context.","clinicalRationale":"Establishes severity and supports intervention timing and type."},{"tier":"specializedAdjunctive","testName":"ECG and functional assessment","modalityTarget":"ECG and functional assessment — Rhythm disturbance and symptom burden","targetCondition":"Rhythm disturbance and symptom burden","expectedFinding":"Arrhythmia and exertional limitation may indicate clinical consequences of valve disease.","clinicalRationale":"Connects imaging severity with the patient's actual functional state."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Renal, frailty and coronary assessment as indicated","modalityTarget":"Renal, frailty and coronary assessment as indicated — Comorbidity affecting procedural benefit or risk","targetCondition":"Comorbidity affecting procedural benefit or risk","expectedFinding":"Organ dysfunction, frailty or coronary disease may alter the Heart Team plan.","clinicalRationale":"Supports an individualised procedure and consent rather than anatomy-only selection."}]},"expected_hash":"a52dca7247e70daa933214ce0e1a1a6d"},{"id":"cbf215a8-cc12-4b87-a821-cef2f005f43c","original_version_id":"cbf215a8-cc12-4b87-a821-cef2f005f43c","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Serial ultrasound biometry with dating review","modalityTarget":"Serial ultrasound biometry with dating review — Small fetal size and reduced growth velocity","targetCondition":"Small fetal size and reduced growth velocity","expectedFinding":"Size centiles and serial growth must be interpreted against reliable gestational dating.","clinicalRationale":"Distinguishes a small fetus from a concerning growth trajectory."},{"tier":"specializedAdjunctive","testName":"Umbilical artery Doppler and amniotic-fluid assessment","modalityTarget":"Umbilical artery Doppler and amniotic-fluid assessment — Placental resistance and fetal compromise risk","targetCondition":"Placental resistance and fetal compromise risk","expectedFinding":"Abnormal Doppler flow or reduced fluid increases concern for placental dysfunction.","clinicalRationale":"Stratifies risk and informs specialist surveillance and delivery planning."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Maternal blood-pressure and pre-eclampsia assessment","modalityTarget":"Maternal blood-pressure and pre-eclampsia assessment — Maternal hypertensive disease accompanying placental dysfunction","targetCondition":"Maternal hypertensive disease accompanying placental dysfunction","expectedFinding":"Elevated pressure, proteinuria or organ dysfunction requires the obstetric hypertension pathway.","clinicalRationale":"Detects a maternal condition that changes urgency and management for both mother and fetus."}]},"expected_hash":"56e67075a3f7d8cabdbcb04e65625b80"},{"id":"35d6fe28-9862-4850-a9ea-7f1d24306001","original_version_id":"35d6fe28-9862-4850-a9ea-7f1d24306001","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Echocardiography","modalityTarget":"Echocardiography — Ventricular dysfunction or important structural disease","targetCondition":"Ventricular dysfunction or important structural disease","expectedFinding":"Reduced ejection fraction, valve disease or relevant diastolic abnormalities help define the phenotype.","clinicalRationale":"Establishes cardiac structure/function and directs phenotype-specific care."},{"tier":"laboratory","testName":"Natriuretic peptide when indicated by the diagnostic pathway","modalityTarget":"Natriuretic peptide when indicated by the diagnostic pathway — A biochemical signal of cardiac wall stress","targetCondition":"A biochemical signal of cardiac wall stress","expectedFinding":"A raised value supports further assessment but is not specific; renal disease, rhythm and body habitus affect interpretation.","clinicalRationale":"Helps triage diagnostic imaging in suspected heart failure."}],"ruleOut":[{"tier":"laboratory","testName":"Creatinine, electrolytes, full blood count and iron status when indicated","modalityTarget":"Creatinine, electrolytes, full blood count and iron status when indicated — Organ dysfunction, electrolyte disturbance and anaemia/iron deficiency","targetCondition":"Organ dysfunction, electrolyte disturbance and anaemia/iron deficiency","expectedFinding":"Abnormal results may contribute to symptoms or limit treatment tolerance.","clinicalRationale":"Establishes a monitoring baseline and identifies potentially correctable comorbidity."},{"tier":"specializedAdjunctive","testName":"12-lead ECG","modalityTarget":"12-lead ECG — Arrhythmia, conduction disturbance or prior ischaemic disease","targetCondition":"Arrhythmia, conduction disturbance or prior ischaemic disease","expectedFinding":"An abnormal rhythm or conduction pattern directs further assessment; ECG alone does not define heart-failure phenotype.","clinicalRationale":"Identifies contributors that can alter treatment or specialist referral."}]},"expected_hash":"07e4a905aba6dee8f3c6588c52c9a069"},{"id":"c21a33c2-d701-4435-8ba7-e8f75db067fa","original_version_id":"c21a33c2-d701-4435-8ba7-e8f75db067fa","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Glucose, electrolytes and measured/calculated osmolality","modalityTarget":"Glucose, electrolytes and measured/calculated osmolality — Severe hyperglycaemia and hyperosmolality","targetCondition":"Severe hyperglycaemia and hyperosmolality","expectedFinding":"Marked glucose elevation with raised osmolality supports HHS in the clinical context.","clinicalRationale":"Defines the metabolic disturbance and monitors the trajectory of correction under the local protocol."},{"tier":"laboratory","testName":"Creatinine, urine output and neurological observations","modalityTarget":"Creatinine, urine output and neurological observations — Kidney hypoperfusion, dehydration and neurological change","targetCondition":"Kidney hypoperfusion, dehydration and neurological change","expectedFinding":"Renal deterioration, low urine output or altered consciousness indicates significant systemic involvement.","clinicalRationale":"Guides individualised fluids and prompts reassessment of neurological deterioration."}],"ruleOut":[{"tier":"laboratory","testName":"Blood ketones and venous blood gas","modalityTarget":"Blood ketones and venous blood gas — Significant ketosis/acidosis or overlap with DKA","targetCondition":"Significant ketosis/acidosis or overlap with DKA","expectedFinding":"Substantial ketonaemia or acidosis suggests mixed DKA/HHS rather than isolated HHS.","clinicalRationale":"Distinguishes overlapping emergencies that require different treatment monitoring."},{"tier":"specializedAdjunctive","testName":"ECG and source-directed precipitant investigation","modalityTarget":"ECG and source-directed precipitant investigation — Infection, ischaemia or another acute trigger","targetCondition":"Infection, ischaemia or another acute trigger","expectedFinding":"Clinical clues select the named tests; abnormalities direct parallel treatment.","clinicalRationale":"Identifies the cause of decompensation without delaying metabolic stabilisation."}]},"expected_hash":"9eec0b67458f167848c7824d97e0bcb3"},{"id":"b3a433fb-5f23-4e19-a23f-97de51d4ef11","original_version_id":"b3a433fb-5f23-4e19-a23f-97de51d4ef11","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Repeated standardised blood-pressure measurement","modalityTarget":"Repeated standardised blood-pressure measurement — Persistent or severe pregnancy-associated hypertension","targetCondition":"Persistent or severe pregnancy-associated hypertension","expectedFinding":"Repeated elevated readings require interpretation with gestation, symptoms and prior pressure.","clinicalRationale":"Confirms the measurement and determines urgency using the pregnancy-specific pathway."},{"tier":"laboratory","testName":"Urine protein assessment","modalityTarget":"Urine protein assessment — Proteinuria accompanying possible pre-eclampsia","targetCondition":"Proteinuria accompanying possible pre-eclampsia","expectedFinding":"Increased protein supports renal involvement; its absence does not exclude pre-eclampsia with other organ dysfunction.","clinicalRationale":"Contributes to diagnosis without allowing a negative result to dismiss concerning maternal findings."}],"ruleOut":[{"tier":"laboratory","testName":"Full blood count/platelets, creatinine and liver tests","modalityTarget":"Full blood count/platelets, creatinine and liver tests — Thrombocytopenia and renal/hepatic organ involvement","targetCondition":"Thrombocytopenia and renal/hepatic organ involvement","expectedFinding":"Falling platelets, rising creatinine or transaminases raises concern for severe disease or HELLP-spectrum complications.","clinicalRationale":"Detects organ dysfunction that changes monitoring, escalation and delivery planning."},{"tier":"specializedAdjunctive","testName":"Fetal growth ultrasound and wellbeing assessment when indicated","modalityTarget":"Fetal growth ultrasound and wellbeing assessment when indicated — Placental dysfunction and fetal compromise","targetCondition":"Placental dysfunction and fetal compromise","expectedFinding":"Growth restriction or abnormal surveillance findings influence obstetric decisions.","clinicalRationale":"Assesses fetal consequences alongside maternal severity."}]},"expected_hash":"8b8edee819c545caa99d02cbbb6507cb"},{"id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254","original_version_id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254","investigations":{"ruleIn":[{"tier":"laboratory","testName":"TSH and free thyroxine","modalityTarget":"TSH and free thyroxine — Primary or central thyroid hormone deficiency","targetCondition":"Primary or central thyroid hormone deficiency","expectedFinding":"High TSH with low free thyroxine supports primary disease; low free thyroxine without appropriately raised TSH suggests a central cause.","clinicalRationale":"Distinguishes biochemical patterns before labelling or treating hypothyroidism."},{"tier":"laboratory","testName":"Thyroid peroxidase antibodies when indicated","modalityTarget":"Thyroid peroxidase antibodies when indicated — Autoimmune thyroid disease","targetCondition":"Autoimmune thyroid disease","expectedFinding":"Positive antibodies support an autoimmune cause but do not measure current thyroid function.","clinicalRationale":"Clarifies aetiology when it changes counselling or follow-up."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Medication, supplement and pituitary assessment when results are discordant","modalityTarget":"Medication, supplement and pituitary assessment when results are discordant — Assay interference, drug effects or pituitary disease","targetCondition":"Assay interference, drug effects or pituitary disease","expectedFinding":"Biotin exposure, relevant medicines or pituitary symptoms may explain a misleading biochemical pattern.","clinicalRationale":"Avoids incorrect diagnosis and directs repeat or specialist testing."}]},"expected_hash":"a1cf450ef38cae9d5e41dab9a7247b86"},{"id":"fb440d70-f345-4ece-be8b-181f403de434","original_version_id":"fb440d70-f345-4ece-be8b-181f403de434","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Continuous fetal heart-rate monitoring with contraction assessment","modalityTarget":"Continuous fetal heart-rate monitoring with contraction assessment — A fetal heart-rate pattern suggesting hypoxia","targetCondition":"A fetal heart-rate pattern suggesting hypoxia","expectedFinding":"Baseline, variability, decelerations and contraction frequency are interpreted together using the locally adopted classification.","clinicalRationale":"Detects a concerning trend and guides prompt obstetric escalation; a trace is not interpreted in isolation."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Maternal observations and focused labour assessment","modalityTarget":"Maternal observations and focused labour assessment — Maternal hypotension, fever, excessive uterine activity or an obstetric emergency","targetCondition":"Maternal hypotension, fever, excessive uterine activity or an obstetric emergency","expectedFinding":"A new maternal abnormality or examination finding can explain the fetal pattern and alter urgency.","clinicalRationale":"Identifies reversible contributors or emergencies while the fetal trace is reassessed."}]},"expected_hash":"b57db46f5ba63ed0ed92840a5bc59bc8"},{"id":"c1e45d3f-fa28-49f1-ab69-3ee4ab9cac6f","original_version_id":"c1e45d3f-fa28-49f1-ab69-3ee4ab9cac6f","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"12-lead ECG","modalityTarget":"12-lead ECG — Ischaemic change, prior infarction or arrhythmia","targetCondition":"Ischaemic change, prior infarction or arrhythmia","expectedFinding":"Resting abnormalities may support cardiac disease; a normal ECG does not exclude coronary disease.","clinicalRationale":"Provides a baseline and identifies findings needing an acute or rhythm-specific pathway."},{"tier":"advancedImaging","testName":"Risk-selected coronary anatomical or functional testing","modalityTarget":"Risk-selected coronary anatomical or functional testing — Obstructive coronary disease or inducible ischaemia","targetCondition":"Obstructive coronary disease or inducible ischaemia","expectedFinding":"The selected study identifies anatomy or functional ischaemia in the appropriate pre-test-risk context.","clinicalRationale":"Clarifies uncertain symptoms and directs management; choose the test through the current cardiology pathway."}],"ruleOut":[{"tier":"laboratory","testName":"Lipids, glycaemia and creatinine","modalityTarget":"Lipids, glycaemia and creatinine — Modifiable vascular risk and kidney impairment","targetCondition":"Modifiable vascular risk and kidney impairment","expectedFinding":"Abnormal lipid/glucose measures or renal dysfunction affects prevention and medicine/procedure safety.","clinicalRationale":"Defines risk-reduction priorities and a baseline for safe care."}]},"expected_hash":"e2e7f187d056e153f06a0c2ae2dd92d9"},{"id":"2886cf83-6050-45de-a152-ea9bced0afb7","original_version_id":"2886cf83-6050-45de-a152-ea9bced0afb7","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serial eGFR, albuminuria and kidney-failure-risk assessment","modalityTarget":"Serial eGFR, albuminuria and kidney-failure-risk assessment — Progression and likelihood of kidney failure","targetCondition":"Progression and likelihood of kidney failure","expectedFinding":"The trend and validated risk estimate inform planning; one eGFR value alone does not determine dialysis initiation.","clinicalRationale":"Allows timely modality, access and transplant discussion according to trajectory and patient preference."},{"tier":"laboratory","testName":"Potassium, bicarbonate, haemoglobin and mineral-bone profile when indicated","modalityTarget":"Potassium, bicarbonate, haemoglobin and mineral-bone profile when indicated — Complications of advanced kidney disease","targetCondition":"Complications of advanced kidney disease","expectedFinding":"Electrolyte, acid-base, anaemia or mineral abnormalities require individualised management.","clinicalRationale":"Identifies complications that affect urgency and readiness for renal replacement options."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Vascular mapping when haemodialysis access is planned","modalityTarget":"Vascular mapping when haemodialysis access is planned — Suitable arteries and veins for access","targetCondition":"Suitable arteries and veins for access","expectedFinding":"Vessel size, patency and anatomy guide the access team's choice.","clinicalRationale":"Supports access planning rather than automatic fistula creation irrespective of goals or modality."}]},"expected_hash":"37c1588c0e57c250bf50d874b2e36293"},{"id":"92061bb4-c2ee-4146-bd7f-b8b6ffc79a54","original_version_id":"92061bb4-c2ee-4146-bd7f-b8b6ffc79a54","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Clinical trajectory and repeated symptom assessment","modalityTarget":"Clinical trajectory and repeated symptom assessment — Dying-phase changes and distress","targetCondition":"Dying-phase changes and distress","expectedFinding":"Progressive decline, altered consciousness and symptom burden are interpreted with the whole clinical trajectory.","clinicalRationale":"Supports recognition, communication and comfort planning while acknowledging uncertainty."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused review for a reversible source of distress","modalityTarget":"Focused review for a reversible source of distress — Pain, retention, constipation or medication-related harm","targetCondition":"Pain, retention, constipation or medication-related harm","expectedFinding":"A specific contributor may be identified by examination and medication review.","clinicalRationale":"Offers proportionate relief; laboratory or imaging tests should be added only if they change goal-concordant care."}]},"expected_hash":"1a72ea2c9dd0f2b7737d8bf6d4612f6b"},{"id":"0f7cd64a-5778-4674-a0e5-e20fa64dc6a2","original_version_id":"0f7cd64a-5778-4674-a0e5-e20fa64dc6a2","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Abdominal examination, bowel history and medication review","modalityTarget":"Abdominal examination, bowel history and medication review — Obstruction pattern, symptom burden and contributing constipation","targetCondition":"Obstruction pattern, symptom burden and contributing constipation","expectedFinding":"Vomiting, distension, reduced stool/flatus and medication effects guide the working assessment.","clinicalRationale":"Identifies the dominant symptoms and potentially reversible contributors before choosing an intervention."},{"tier":"advancedImaging","testName":"CT abdomen/pelvis when results will alter management","modalityTarget":"CT abdomen/pelvis when results will alter management — Obstruction site, extent and procedural options","targetCondition":"Obstruction site, extent and procedural options","expectedFinding":"A transition point, multifocal disease or a complication affects surgical, endoscopic or decompressive choices.","clinicalRationale":"Clarifies whether an intervention is feasible and consistent with the patient's goals."}],"ruleOut":[{"tier":"laboratory","testName":"Creatinine and electrolytes when clinically useful","modalityTarget":"Creatinine and electrolytes when clinically useful — Dehydration and metabolic disturbance","targetCondition":"Dehydration and metabolic disturbance","expectedFinding":"Renal impairment or electrolyte losses may accompany vomiting and poor intake.","clinicalRationale":"Guides proportionate fluids and symptom-medicine safety."}]},"expected_hash":"59794fc9d32c6e6355708ab471792e11"},{"id":"1759a9d1-015f-40c7-8a11-e8e54f52991d","original_version_id":"1759a9d1-015f-40c7-8a11-e8e54f52991d","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Blood cultures and source cultures when indicated","modalityTarget":"Blood cultures and source cultures when indicated — The causative organism","targetCondition":"The causative organism","expectedFinding":"Growth and susceptibility results help target therapy; negative cultures do not exclude sepsis.","clinicalRationale":"Supports antimicrobial narrowing; collection must not cause a meaningful delay to urgent treatment."},{"tier":"laboratory","testName":"Lactate and renal/liver/coagulation profile","modalityTarget":"Lactate and renal/liver/coagulation profile — Hypoperfusion and organ dysfunction","targetCondition":"Hypoperfusion and organ dysfunction","expectedFinding":"Raised lactate or deteriorating organ indices increases concern; a normal lactate does not exclude maternal sepsis.","clinicalRationale":"Assesses severity and response alongside maternal observations and the current sepsis bundle."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Source-directed ultrasound or other imaging","modalityTarget":"Source-directed ultrasound or other imaging — Retained infected tissue, a collection or another treatable focus","targetCondition":"Retained infected tissue, a collection or another treatable focus","expectedFinding":"A localised focus may require drainage, evacuation or another source-control intervention.","clinicalRationale":"Selects the appropriate source-control plan with obstetric and relevant specialist teams."}]},"expected_hash":"5d7b9626bf919ad7c0ed6475014750e3"},{"id":"e1586073-d5ce-469b-a54a-2eb47edb5a33","original_version_id":"e1586073-d5ce-469b-a54a-2eb47edb5a33","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Glycaemia, lipid and liver assessment when indicated","modalityTarget":"Glycaemia, lipid and liver assessment when indicated — Metabolic comorbidity and hepatic risk","targetCondition":"Metabolic comorbidity and hepatic risk","expectedFinding":"Diabetes, dyslipidaemia or hepatic abnormality may require optimisation or further assessment.","clinicalRationale":"Defines the expected metabolic benefit and perioperative risk."},{"tier":"laboratory","testName":"Nutritional assessment and targeted deficiency tests","modalityTarget":"Nutritional assessment and targeted deficiency tests — Pre-existing nutrient deficiency or inadequate intake","targetCondition":"Pre-existing nutrient deficiency or inadequate intake","expectedFinding":"Iron, vitamin or other selected abnormalities depend on diet, history and the proposed procedure.","clinicalRationale":"Corrects deficiencies and establishes a plan for procedure-specific long-term monitoring."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Sleep-apnoea and psychological assessment","modalityTarget":"Sleep-apnoea and psychological assessment — Respiratory and behavioural risks affecting surgery and recovery","targetCondition":"Respiratory and behavioural risks affecting surgery and recovery","expectedFinding":"Sleep-apnoea symptoms or identified support needs direct specialist review and testing.","clinicalRationale":"Supports safe anaesthesia, informed expectations and sustained postoperative care."}]},"expected_hash":"a83b6ec246265d80b9afa72360be02ca"},{"id":"f7b63e19-fee5-4238-a31a-f115d1beb66e","original_version_id":"f7b63e19-fee5-4238-a31a-f115d1beb66e","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Focused symptom, bowel and medication assessment","modalityTarget":"Focused symptom, bowel and medication assessment — Drug-related, gastrointestinal or central triggers","targetCondition":"Drug-related, gastrointestinal or central triggers","expectedFinding":"Timing, vomiting pattern, bowel function and recent medicine changes help identify the mechanism.","clinicalRationale":"Selects symptom treatment according to the likely cause and feasible administration route."}],"ruleOut":[{"tier":"laboratory","testName":"Glucose, electrolytes, calcium and creatinine when results change care","modalityTarget":"Glucose, electrolytes, calcium and creatinine when results change care — A metabolic contributor or complication of vomiting","targetCondition":"A metabolic contributor or complication of vomiting","expectedFinding":"Hypercalcaemia, dysglycaemia, kidney impairment or electrolyte loss may explain symptoms.","clinicalRationale":"Detects reversible causes and supports safe, proportionate symptom management."},{"tier":"advancedImaging","testName":"Targeted imaging if obstruction or another structural cause is suspected","modalityTarget":"Targeted imaging if obstruction or another structural cause is suspected — A structural cause amenable to intervention","targetCondition":"A structural cause amenable to intervention","expectedFinding":"Imaging may demonstrate obstruction or another focal lesion relevant to the symptoms.","clinicalRationale":"Use when the finding can change a goal-concordant intervention; avoid routine imaging without a decision."}]},"expected_hash":"2c1d35ca241a54008b79f2f829b55aff"},{"id":"96362735-4fed-4dc9-9c7b-3a8d10d1cfbd","original_version_id":"96362735-4fed-4dc9-9c7b-3a8d10d1cfbd","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Weight, height and blood-pressure measurement with consent","modalityTarget":"Weight, height and blood-pressure measurement with consent — Weight-related risk and elevated blood pressure","targetCondition":"Weight-related risk and elevated blood pressure","expectedFinding":"BMI and pressure provide risk measures but must be interpreted with body composition, ethnicity and the person's context.","clinicalRationale":"Establishes a respectful baseline and directs risk-focused care."},{"tier":"laboratory","testName":"HbA1c or fasting glucose and lipid profile when indicated","modalityTarget":"HbA1c or fasting glucose and lipid profile when indicated — Diabetes and dyslipidaemia","targetCondition":"Diabetes and dyslipidaemia","expectedFinding":"Abnormal glycaemia or lipids identifies cardiometabolic comorbidity.","clinicalRationale":"Finds conditions that influence treatment priorities and eligibility for interventions."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Sleep-apnoea, liver, mood and medication assessment","modalityTarget":"Sleep-apnoea, liver, mood and medication assessment — Associated disease or a medication contributor","targetCondition":"Associated disease or a medication contributor","expectedFinding":"Snoring/daytime sleepiness, hepatic clues, mood concerns or weight-promoting medicines direct targeted follow-up.","clinicalRationale":"Identifies complications and modifiable contributors; further testing follows the specific suspected condition."}]},"expected_hash":"190ce49008a75c83da62ee5b465aaeee"},{"id":"44ad5ad7-8c67-4c70-8725-cd5ca7c34ce9","original_version_id":"44ad5ad7-8c67-4c70-8725-cd5ca7c34ce9","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Focused joint and functional examination","modalityTarget":"Focused joint and functional examination — A mechanical joint-pain pattern and functional limitation","targetCondition":"A mechanical joint-pain pattern and functional limitation","expectedFinding":"Activity-related pain, restricted motion and function support the assessment; a hot swollen joint needs a different urgent differential.","clinicalRationale":"Establishes the clinical pattern and the effect on daily life."}],"ruleOut":[{"tier":"firstLineImaging","testName":"Joint radiograph when atypical features or an intervention require it","modalityTarget":"Joint radiograph when atypical features or an intervention require it — Structural disease or an alternative bony lesion","targetCondition":"Structural disease or an alternative bony lesion","expectedFinding":"Degenerative change may support the diagnosis, but imaging severity does not directly measure pain.","clinicalRationale":"Answers a specific diagnostic or planning question rather than routinely imaging typical uncomplicated symptoms."},{"tier":"specializedAdjunctive","testName":"Medication and comorbidity assessment","modalityTarget":"Medication and comorbidity assessment — Renal, gastrointestinal or cardiovascular risk from analgesic choices","targetCondition":"Renal, gastrointestinal or cardiovascular risk from analgesic choices","expectedFinding":"Relevant disease, interactions or previous adverse effects may change the pain plan.","clinicalRationale":"Supports safer treatment and targeted monitoring."}]},"expected_hash":"d94d2f8990edb365efa0052cd4e17678"},{"id":"267bf607-b37b-4029-b76a-761cc3d9e3be","original_version_id":"267bf607-b37b-4029-b76a-761cc3d9e3be","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Fracture-risk, falls and medication assessment","modalityTarget":"Fracture-risk, falls and medication assessment — Fragility fracture history and future fracture risk","targetCondition":"Fragility fracture history and future fracture risk","expectedFinding":"Prior low-trauma fractures, fall risk and relevant exposures inform the locally adopted risk estimate.","clinicalRationale":"Identifies who benefits from bone-health investigation and prevention."},{"tier":"specializedAdjunctive","testName":"DXA when indicated","modalityTarget":"DXA when indicated — Low bone mineral density","targetCondition":"Low bone mineral density","expectedFinding":"Site-specific density scores are interpreted according to age and clinical context.","clinicalRationale":"Supports diagnosis and risk assessment; bone density alone does not capture all fracture risk."}],"ruleOut":[{"tier":"laboratory","testName":"Targeted calcium, renal, vitamin D or other cause-specific tests","modalityTarget":"Targeted calcium, renal, vitamin D or other cause-specific tests — A secondary cause or factor affecting treatment safety","targetCondition":"A secondary cause or factor affecting treatment safety","expectedFinding":"An identified abnormality directs further cause-specific assessment.","clinicalRationale":"Selects tests from the history and examination before finalising bone-protection treatment."}]},"expected_hash":"b3c509b667ccccb1e3906ccebd25677d"},{"id":"c52eac83-6f42-4d81-b132-40d59fa4544b","original_version_id":"c52eac83-6f42-4d81-b132-40d59fa4544b","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Quantified blood loss and serial maternal observations","modalityTarget":"Quantified blood loss and serial maternal observations — Ongoing haemorrhage and circulatory compromise","targetCondition":"Ongoing haemorrhage and circulatory compromise","expectedFinding":"Continuing blood loss, tachycardia or falling pressure raises concern; physiological change may lag behind bleeding.","clinicalRationale":"Tracks severity and response while resuscitation and cause control proceed."},{"tier":"laboratory","testName":"Full blood count, coagulation and fibrinogen","modalityTarget":"Full blood count, coagulation and fibrinogen — Anaemia, platelet deficiency and coagulopathy","targetCondition":"Anaemia, platelet deficiency and coagulopathy","expectedFinding":"Falling haemoglobin/platelets or abnormal coagulation/fibrinogen informs blood-product assessment; early haemoglobin can be misleading.","clinicalRationale":"Guides the haemorrhage/transfusion pathway without delaying immediate treatment."},{"tier":"laboratory","testName":"Blood group and crossmatch","modalityTarget":"Blood group and crossmatch — Compatible blood products","targetCondition":"Compatible blood products","expectedFinding":"Compatibility testing enables appropriate transfusion support.","clinicalRationale":"Prepares urgently needed products through the local major-haemorrhage protocol."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused obstetric examination with ultrasound when useful","modalityTarget":"Focused obstetric examination with ultrasound when useful — Atony, trauma, retained tissue or another bleeding cause","targetCondition":"Atony, trauma, retained tissue or another bleeding cause","expectedFinding":"Uterine tone, genital trauma or retained tissue directs cause-specific intervention.","clinicalRationale":"Identifies the source; imaging must not delay action for clinically evident haemorrhage."}]},"expected_hash":"d66ca8d870a7e7e8cac895777b23ecd4"},{"id":"040068a6-0d8f-4382-acf5-b28685eb6708","original_version_id":"040068a6-0d8f-4382-acf5-b28685eb6708","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Disease-control and medication review","modalityTarget":"Disease-control and medication review — Maternal conditions or medicines that may affect pregnancy","targetCondition":"Maternal conditions or medicines that may affect pregnancy","expectedFinding":"Suboptimal disease control or potentially harmful exposures require an individualised plan.","clinicalRationale":"Allows safer pregnancy preparation and specialist input before conception."},{"tier":"laboratory","testName":"Blood pressure and risk-selected glycaemia assessment","modalityTarget":"Blood pressure and risk-selected glycaemia assessment — Unrecognised or poorly controlled cardiometabolic disease","targetCondition":"Unrecognised or poorly controlled cardiometabolic disease","expectedFinding":"Elevated pressure or glycaemia requires confirmation and optimisation.","clinicalRationale":"Identifies modifiable maternal risk before pregnancy."}],"ruleOut":[{"tier":"laboratory","testName":"Pregnancy test when clinically relevant and with consent","modalityTarget":"Pregnancy test when clinically relevant and with consent — An existing pregnancy","targetCondition":"An existing pregnancy","expectedFinding":"A positive result changes investigation, medicine and counselling decisions.","clinicalRationale":"Avoids treating the encounter as preconception when pregnancy has already begun."},{"tier":"specializedAdjunctive","testName":"Immunisation and risk-based infection/genetic history","modalityTarget":"Immunisation and risk-based infection/genetic history — Missing protection or a specific inherited/infectious risk","targetCondition":"Missing protection or a specific inherited/infectious risk","expectedFinding":"Records and relevant family/exposure history select any indicated further tests.","clinicalRationale":"Targets preventive care using current Saudi guidance instead of blanket testing."}]},"expected_hash":"f02a24b9d162d4621d9ba6dab6a3151e"},{"id":"db633270-3fb9-4b9e-97bb-4a54376ad9ab","original_version_id":"db633270-3fb9-4b9e-97bb-4a54376ad9ab","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Sterile speculum examination and a validated membrane test when uncertain","modalityTarget":"Sterile speculum examination and a validated membrane test when uncertain — Amniotic-fluid leakage","targetCondition":"Amniotic-fluid leakage","expectedFinding":"Pooling or a positive validated test supports rupture in context; contamination and assay limitations may affect results.","clinicalRationale":"Confirms the diagnosis while avoiding unnecessary repeated digital examination."},{"tier":"specializedAdjunctive","testName":"Ultrasound when indicated","modalityTarget":"Ultrasound when indicated — Amniotic-fluid volume, presentation and growth","targetCondition":"Amniotic-fluid volume, presentation and growth","expectedFinding":"Reduced fluid may support the context but cannot independently confirm or exclude rupture.","clinicalRationale":"Assists pregnancy assessment and planning alongside examination and gestation."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Maternal observations and fetal heart assessment","modalityTarget":"Maternal observations and fetal heart assessment — Infection or fetal compromise","targetCondition":"Infection or fetal compromise","expectedFinding":"Fever, maternal/fetal tachycardia or a concerning fetal pattern requires urgent obstetric reassessment.","clinicalRationale":"Identifies complications that change the surveillance and delivery plan."}]},"expected_hash":"220d25b6499e524842406094eccc0b78"},{"id":"26995ba0-e325-44a3-a579-c02e7656b14d","original_version_id":"26995ba0-e325-44a3-a579-c02e7656b14d","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Contraction, cervical and gestation assessment","modalityTarget":"Contraction, cervical and gestation assessment — Labour-associated cervical change before term","targetCondition":"Labour-associated cervical change before term","expectedFinding":"Contractions with progressive cervical change support labour; isolated contractions are insufficient.","clinicalRationale":"Determines whether urgent preterm-birth planning is needed."},{"tier":"specializedAdjunctive","testName":"Transvaginal cervical length or a validated prediction test when indicated","modalityTarget":"Transvaginal cervical length or a validated prediction test when indicated — Risk of imminent preterm birth","targetCondition":"Risk of imminent preterm birth","expectedFinding":"A short cervix or test result is interpreted within the locally adopted gestation-specific algorithm.","clinicalRationale":"Refines risk when clinical diagnosis is uncertain; eligibility and interpretation follow the obstetric pathway."}],"ruleOut":[{"tier":"laboratory","testName":"Maternal observations, urine testing and membrane assessment when indicated","modalityTarget":"Maternal observations, urine testing and membrane assessment when indicated — Infection or membrane rupture contributing to symptoms","targetCondition":"Infection or membrane rupture contributing to symptoms","expectedFinding":"An infectious finding or fluid leakage directs a separate treatment pathway.","clinicalRationale":"Detects causes and complications that change management and the appropriateness of examination/testing."}]},"expected_hash":"5f6fb4cacdc5a357c868bb8c3f7be6d6"},{"id":"5a547d53-3e80-4901-b33f-43e180bf1ae7","original_version_id":"5a547d53-3e80-4901-b33f-43e180bf1ae7","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Respiratory symptom assessment and specialist-selected function tests","modalityTarget":"Respiratory symptom assessment and specialist-selected function tests — Respiratory muscle weakness or ventilatory failure","targetCondition":"Respiratory muscle weakness or ventilatory failure","expectedFinding":"Declining respiratory function, orthopnoea or sleep-related symptoms prompt respiratory review.","clinicalRationale":"Identifies respiratory support needs before a crisis, consistent with the person's preferences."},{"tier":"specializedAdjunctive","testName":"Swallowing, nutrition and communication assessment","modalityTarget":"Swallowing, nutrition and communication assessment — Dysphagia, aspiration risk or loss of communication","targetCondition":"Dysphagia, aspiration risk or loss of communication","expectedFinding":"Unsafe swallowing, weight loss or communication barriers identify support needs.","clinicalRationale":"Guides feeding, communication aids and anticipatory planning."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Focused review for new reversible deterioration","modalityTarget":"Focused review for new reversible deterioration — Infection, medication effects or another superimposed problem","targetCondition":"Infection, medication effects or another superimposed problem","expectedFinding":"A new change outside the expected trajectory directs specific additional tests.","clinicalRationale":"Avoids assuming every decline is inevitable progression; investigate when the result changes goal-concordant care."}]},"expected_hash":"73cdc348bd7102bb7236ae1e00489771"},{"id":"0fa54350-8904-4f17-a688-c1b27946690d","original_version_id":"0fa54350-8904-4f17-a688-c1b27946690d","investigations":{"ruleIn":[{"tier":"laboratory","testName":"PSA with history and examination","modalityTarget":"PSA with history and examination — A prostate-cancer signal in clinical context","targetCondition":"A prostate-cancer signal in clinical context","expectedFinding":"An elevated or changing PSA may warrant further assessment; benign enlargement and inflammation can also raise it.","clinicalRationale":"Supports risk assessment without using PSA alone to diagnose cancer."},{"tier":"advancedImaging","testName":"Prostate MRI and biopsy when indicated","modalityTarget":"Prostate MRI and biopsy when indicated — A suspicious lesion and histological diagnosis/grade","targetCondition":"A suspicious lesion and histological diagnosis/grade","expectedFinding":"MRI guides risk and biopsy strategy; tissue histology establishes tumour grade and diagnosis.","clinicalRationale":"Confirms disease and informs management before treatment selection."}],"ruleOut":[{"tier":"advancedImaging","testName":"Risk-appropriate staging imaging","modalityTarget":"Risk-appropriate staging imaging — Nodal or distant spread","targetCondition":"Nodal or distant spread","expectedFinding":"The selected imaging study identifies disease extent according to the cancer-risk category.","clinicalRationale":"Prevents under- or over-staging and guides multidisciplinary treatment planning."}]},"expected_hash":"43c052be450417b29af1136d97bdcfc2"},{"id":"3436a68e-5207-48f6-b840-af4d87529129","original_version_id":"3436a68e-5207-48f6-b840-af4d87529129","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Prompt fetal heart assessment","modalityTarget":"Prompt fetal heart assessment — Fetal viability and immediate heart-rate concern","targetCondition":"Fetal viability and immediate heart-rate concern","expectedFinding":"A confirmed fetal heartbeat establishes viability at assessment; absent or abnormal findings require urgent obstetric evaluation.","clinicalRationale":"Identifies immediate risk; home Doppler or reassurance from one sound does not replace assessment."},{"tier":"specializedAdjunctive","testName":"Gestation-appropriate cardiotocography","modalityTarget":"Gestation-appropriate cardiotocography — A concerning fetal heart-rate pattern","targetCondition":"A concerning fetal heart-rate pattern","expectedFinding":"A non-reassuring pattern changes urgency; a reassuring trace does not exclude all placental or growth problems.","clinicalRationale":"Evaluates short-term fetal wellbeing through the locally adopted pregnancy pathway."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Growth, fluid and Doppler ultrasound when indicated","modalityTarget":"Growth, fluid and Doppler ultrasound when indicated — Growth restriction or placental dysfunction","targetCondition":"Growth restriction or placental dysfunction","expectedFinding":"Small size, reduced fluid or abnormal Doppler may explain risk despite a reassuring initial assessment.","clinicalRationale":"Investigates persistent/recurrent concern or relevant risk factors and guides senior follow-up."}]},"expected_hash":"f793cae3b1c1fb3c101aea8012be97cd"},{"id":"8091cd18-2256-40b7-8c6d-7557ac5e2fdf","original_version_id":"8091cd18-2256-40b7-8c6d-7557ac5e2fdf","investigations":{"ruleIn":[{"tier":"laboratory","testName":"Immediate bedside glucose with repeat measurement","modalityTarget":"Immediate bedside glucose with repeat measurement — Low glucose and response to correction","targetCondition":"Low glucose and response to correction","expectedFinding":"A low result supports hypoglycaemia; a repeat measurement checks recovery or recurrence.","clinicalRationale":"Confirms the reversible emergency and monitors treatment without delaying immediate care."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Medication, intake and renal/hepatic assessment","modalityTarget":"Medication, intake and renal/hepatic assessment — Drug accumulation, missed intake or impaired glucose regulation","targetCondition":"Drug accumulation, missed intake or impaired glucose regulation","expectedFinding":"Recent insulin/sulfonylurea exposure, poor intake or organ dysfunction may explain prolonged or recurrent episodes.","clinicalRationale":"Identifies the trigger and determines monitoring needs and recurrence prevention."},{"tier":"laboratory","testName":"Specialist-directed critical-sample testing for unexplained recurrent episodes","modalityTarget":"Specialist-directed critical-sample testing for unexplained recurrent episodes — Endogenous or exogenous hyperinsulinaemia and other causes","targetCondition":"Endogenous or exogenous hyperinsulinaemia and other causes","expectedFinding":"Selected glucose, insulin-related and exposure assays require interpretation at the time of a documented episode.","clinicalRationale":"Investigates unexplained hypoglycaemia; sample collection must never delay emergency correction."}]},"expected_hash":"a89cc3f43525476e78edba255427fcf5"},{"id":"e62a9981-ea21-4643-abb1-19f7ffc37789","original_version_id":"e62a9981-ea21-4643-abb1-19f7ffc37789","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Structured tobacco-use and dependence assessment","modalityTarget":"Structured tobacco-use and dependence assessment — Nicotine dependence and withdrawal risk","targetCondition":"Nicotine dependence and withdrawal risk","expectedFinding":"Product use, frequency, time to first use and prior withdrawal define the dependence pattern.","clinicalRationale":"Matches behavioural support and treatment planning to the person's needs."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Pregnancy, mental-health and medication review","modalityTarget":"Pregnancy, mental-health and medication review — Factors affecting cessation treatment safety and follow-up","targetCondition":"Factors affecting cessation treatment safety and follow-up","expectedFinding":"Pregnancy, relevant illness, interactions or prior adverse effects may change the plan.","clinicalRationale":"Selects suitable support through current Saudi cessation services; routine laboratory testing is not needed for every cessation encounter."}]},"expected_hash":"3fc0bf090b4462b256715191a15bbd2f"},{"id":"3f198bb7-8829-4e91-b35c-e46ad1e07eb5","original_version_id":"3f198bb7-8829-4e91-b35c-e46ad1e07eb5","investigations":{"ruleIn":[{"tier":"laboratory","testName":"HbA1c or an appropriate glucose-based measure","modalityTarget":"HbA1c or an appropriate glucose-based measure — Current glycaemic control","targetCondition":"Current glycaemic control","expectedFinding":"The result shows overall control in context; use glucose-based measures when HbA1c is unreliable.","clinicalRationale":"Guides shared treatment review while considering hypoglycaemia, frailty and individual goals."},{"tier":"laboratory","testName":"Creatinine/eGFR and urine albumin-creatinine ratio","modalityTarget":"Creatinine/eGFR and urine albumin-creatinine ratio — Reduced filtration or albuminuria","targetCondition":"Reduced filtration or albuminuria","expectedFinding":"Persistent abnormalities identify diabetic or other kidney disease and modify risk.","clinicalRationale":"Detects renal complications and informs medication safety and monitoring."}],"ruleOut":[{"tier":"specializedAdjunctive","testName":"Retinal assessment and foot-risk examination","modalityTarget":"Retinal assessment and foot-risk examination — Retinopathy, neuropathy, ischaemia or ulceration","targetCondition":"Retinopathy, neuropathy, ischaemia or ulceration","expectedFinding":"Retinal abnormalities, reduced protective sensation or abnormal pulses require tracked follow-up.","clinicalRationale":"Finds complications early and directs preventive or urgent specialist care."},{"tier":"laboratory","testName":"Lipid profile and cardiovascular assessment","modalityTarget":"Lipid profile and cardiovascular assessment — Atherogenic risk and established vascular disease","targetCondition":"Atherogenic risk and established vascular disease","expectedFinding":"Lipid abnormalities and vascular history influence prevention priorities.","clinicalRationale":"Addresses cardiovascular risk alongside glucose control under the current Saudi diabetes pathway."}]},"expected_hash":"05aaffee3b75a5297c25ab69446e0dcc"},{"id":"cbd9f91f-e176-4601-9bf4-b4f2f7e96deb","original_version_id":"cbd9f91f-e176-4601-9bf4-b4f2f7e96deb","investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"Compression ultrasound for suspected DVT","modalityTarget":"Compression ultrasound for suspected DVT — Venous thrombosis","targetCondition":"Venous thrombosis","expectedFinding":"A non-compressible vein supports DVT; persistent suspicion after a negative study requires the pregnancy-specific follow-up pathway.","clinicalRationale":"Provides first-line objective assessment of symptomatic leg-vein thrombosis."},{"tier":"advancedImaging","testName":"Pregnancy-adapted PE assessment and specialist-selected chest imaging","modalityTarget":"Pregnancy-adapted PE assessment and specialist-selected chest imaging — Pulmonary embolism","targetCondition":"Pulmonary embolism","expectedFinding":"The selected V/Q or CT pulmonary angiographic study is interpreted within the pregnancy diagnostic pathway.","clinicalRationale":"Confirms or excludes PE with an appropriate balance of clinical risk, radiation and contrast considerations."}],"ruleOut":[{"tier":"laboratory","testName":"Full blood count, creatinine and bleeding assessment","modalityTarget":"Full blood count, creatinine and bleeding assessment — Anaemia, thrombocytopenia, renal impairment or bleeding risk","targetCondition":"Anaemia, thrombocytopenia, renal impairment or bleeding risk","expectedFinding":"Abnormal platelets/haemoglobin or renal function may change anticoagulation and monitoring.","clinicalRationale":"Establishes treatment safety without delaying urgent care for a suspected high-risk thromboembolic event."}]},"expected_hash":"fe156badae1866bedf7eb3c31a5ae0ef"}]$marifa_inv$::jsonb)
 as x(id uuid, original_version_id uuid, expected_hash text, investigations jsonb);
do $guard$
begin
 if (select count(*) from marifa_inv_payload) <> 61 then raise exception 'Unexpected revision count'; end if;
 if (select count(*) from public.clinical_guidelines where organization_id is null and status in ('approved','published')) <> 71 then raise exception 'Catalogue changed: reconcile before revision'; end if;
 if exists (
   select 1 from marifa_inv_payload p left join public.guideline_versions v on v.id=p.original_version_id and v.guideline_id=p.id and v.is_current
   where v.id is null or md5(v.content::text) <> p.expected_hash
 ) then raise exception 'Before-image guard failed'; end if;
 if exists (
   select 1 from public.guideline_versions v join marifa_inv_payload p on p.id=v.guideline_id
   where v.version='investigations-2026-10-11-v1' and
    (v.content->'investigations' <> p.investigations or v.is_current or v.status <> 'under_review')
 ) then raise exception 'A different revision already exists; do not overwrite it'; end if;
end $guard$;
insert into public.guideline_versions
(guideline_id,version,version_number,status,content,change_summary,source_title,issuing_organization,source_url,jurisdiction,publication_date,last_verified_date,review_date,created_by,is_current)
select v.guideline_id,'investigations-2026-10-11-v1','investigations-2026-10-11-v1','under_review',
 v.content || jsonb_build_object('investigations',p.investigations,'status','under_review','version','investigations-2026-10-11-v1','clinicalReviewStatus','pending'),
 'Codex-prepared investigation revision: named assessments, specific targets, findings/limitations and decision rationale. Full textbook chapter verification and current Saudi/local clinical review remain pending. Prior current version and all other content preserved; no clinical approval or publication claimed.',
 v.source_title,v.issuing_organization,v.source_url,v.jurisdiction,v.publication_date,null,'2026-10-11',v.created_by,false
from marifa_inv_payload p join public.guideline_versions v on v.id=p.original_version_id
on conflict (guideline_id,version) do nothing;
do $after$
begin
 if (select count(*) from public.guideline_versions where version='investigations-2026-10-11-v1' and status='under_review' and not is_current and approved_by is null and approved_at is null and published_at is null) <> 61 then raise exception 'Revision verification failed'; end if;
 if exists (select 1 from marifa_inv_payload p join public.guideline_versions v on v.id=p.original_version_id where md5(v.content::text) <> p.expected_hash or not v.is_current) then raise exception 'Original content changed'; end if;
end $after$;
commit;
select count(*) review_drafts, sum(jsonb_array_length(content #> '{investigations,ruleIn}') + jsonb_array_length(content #> '{investigations,ruleOut}')) named_assessments
from public.guideline_versions where version='investigations-2026-10-11-v1' and status='under_review' and not is_current;
